import requests

def solve(inputs):
    """
    Searches for countries using the REST Countries v5 API based on provided inputs.

    Args:
        inputs (dict): A dictionary containing:
            - 'results_to_skip': Number of results to skip (offset).
            - 'included_attributes': List of attributes to include in the response.
            - 'search_text': Search term for country names.
            - 'credential': API key or token for authentication.

    Returns:
        dict or None: Decoded JSON response if successful, None if no results found.
        Raises:
            Exception: If the HTTP response is unsuccessful.
    """
    base_url = "https://restcountries.com/v3.1"
    endpoint = f"{base_url}/search"

    params = {
        'search': inputs['search_text'],
        'skip': inputs['results_to_skip']
    }

    headers = {
        'Authorization': f'Bearer {inputs["credential"]}'
    }

    try:
        response = requests.get(endpoint, params=params, headers=headers)
        response.raise_for_status()  # Raises an HTTPError for bad responses (4xx or 5xx)

        data = response.json()

        if not data:
            return None

        # Filter attributes if specified
        if inputs['included_attributes']:
            filtered_data = []
            for country in data:
                filtered_country = {}
                for key in inputs['included_attributes']:
                    if key in country:
                        filtered_country[key] = country[key]
                filtered_data.append(filtered_country)
            return filtered_data

        return data

    except requests.exceptions.HTTPError as e:
        raise Exception(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise Exception(f"Request failed: {e}")

