def solve(inputs):
    """
    Updates a milestone in a GitHub repository using the REST API version 2026-03-10.

    Args:
        inputs (dict): A dictionary containing:
            - 'repository_owner' (str): The account owner of the repository.
            - 'repository_name' (str): The name of the repository without the .git extension.
            - 'milestone_number' (int): The number that identifies the milestone.
            - 'new_description' (str): The new value for the description attribute.
            - 'credential' (dict): A dictionary containing authentication details, assumed to have necessary permissions.

    Returns:
        dict or None: The decoded JSON response if successful and non-empty, otherwise None.

    Raises:
        requests.exceptions.RequestException: If an unsuccessful HTTP response is received.
    """

    # Extract inputs
    owner = inputs['repository_owner']
    repo = inputs['repository_name']
    milestone_number = inputs['milestone_number']
    new_description = inputs['new_description']
    credential = inputs['credential']

    # Construct the API URL for updating a milestone
    # Format: https://api.github.com/repos/{owner}/{repo}/milestones/{milestone_number}
    url = f"https://api.github.com/repos/{owner}/{repo}/milestones/{milestone_number}"

    # Prepare headers with authentication
    # Assuming 'credential' contains 'token' for Basic Auth or Bearer Token
    if 'token' in credential:
        auth_token = credential['token']
        headers = {
            "Authorization": f"Bearer {auth_token}",
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2026-03-10"
        }
    else:
        # Fallback to Basic Auth if token is not provided but username/password are
        if 'username' in credential and 'password' in credential:
            auth = (credential['username'], credential['password'])
            headers = {
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2026-03-10"
            }
        else:
            raise ValueError("Credential must contain 'token' or both 'username' and 'password'.")

    # Prepare the payload for updating the milestone description
    payload = {
        "description": new_description
    }

    # Send the PUT request to update the milestone
    response = requests.put(url, headers=headers, json=payload)

    # Check if the response is successful (2xx status code)
    if 200 <= response.status_code < 300:
        # GitHub typically returns a 204 No Content for successful updates without returning a body
        if response.status_code == 204:
            return None
        else:
            try:
                return response.json()
            except ValueError:
                # If JSON decoding fails, return the raw text as a fallback
                return response.text
    else:
        # Raise an exception for unsuccessful HTTP responses
        raise requests.exceptions.HTTPError(
            f"Request failed with status code {response.status_code}: {response.text}"
        )

