import requests

def solve(inputs):
    """
    Adds a new pet to the Swagger Petstore (OpenAPI 3) store.

    Args:
        inputs (dict): A dictionary containing:
            - 'new_name' (str): Name of the new pet.
            - 'new_category' (str): Category of the new pet.
            - 'new_photo_links' (list or str): Photo URLs for the new pet.
            - 'credential' (dict): Caller-supplied credentials (e.g., username/password).

    Returns:
        str or None: The 'name' attribute from the response, or None if absent or on empty success.

    Raises:
        requests.exceptions.RequestException: If the HTTP request fails.
    """
    base_url = "https://petstore.swagger.io/v2"
    endpoint = f"{base_url}/pet"

    # Prepare the payload based on OpenAPI 3 Pet schema expectations
    payload = {
        "name": inputs["new_name"],
        "category": {"name": inputs["new_category"]},
        "photoUrls": inputs.get("new_photo_links", []) if isinstance(inputs.get("new_photo_links"), list) else [inputs["new_photo_links"]] if inputs.get("new_photo_links") else []
    }

    # Prepare headers with Bearer token or Basic Auth if provided in credential
    auth = None
    if "credential" in inputs:
        cred = inputs["credential"]
        # Assuming 'credential' might be a dict like {'username': ..., 'password': ...} or {'token': ...}
        if isinstance(cred, dict):
            if "token" in cred:
                headers = {"Authorization": f"Bearer {cred['token']}"}
            elif "username" in cred and "password" in cred:
                auth = (cred["username"], cred["password"])
            else:
                # Fallback or error handling for unknown credential format
                raise ValueError("Unsupported credential format. Expected 'token' or 'username/password'.")
        else:
            raise ValueError("Credential must be a dictionary.")

    try:
        response = requests.post(endpoint, json=payload, auth=auth, headers=headers if "headers" in locals() else {})
        response.raise_for_status()  # Raises HTTPError for bad responses (4xx or 5xx)

        # Return the 'name' from the response JSON if present, otherwise None
        return response.json().get("name")

    except requests.exceptions.HTTPError as e:
        raise RuntimeError(f"Failed to add pet. HTTP Error: {e}") from e
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Request failed: {e}") from e

import requests

def solve(inputs):
    """
    Retrieves one page of countries from REST Countries v5 API based on provided inputs.

    Args:
        inputs (dict): A dictionary containing:
            - included_attributes (list): Attributes to include in the response.
            - search_text (str): Search term for filtering countries.
            - credential (str): Caller-supplied credential (e.g., API key or token).

    Returns:
        dict or None: Decoded JSON response if successful. Returns None for an empty list of countries.

    Raises:
        Exception: If the HTTP response is unsuccessful.
    """
    base_url = "https://restcountries.com/v5.1"
    endpoint = "/data/countries"

    params = {
        "included": ",".join(inputs["included_attributes"]) if inputs["included_attributes"] else None,
        "search": inputs["search_text"] if inputs["search_text"] else None
    }

    headers = {
        "Authorization": f"Bearer {inputs['credential']}" if inputs.get("credential") else ""
    }

    url = f"{base_url}{endpoint}"

    try:
        response = requests.get(url, params=params, headers=headers)

        if response.status_code == 200:
            data = response.json()
            return None if not data else data
        elif response.status_code == 401:
            raise Exception("Unauthorized access. Check your credentials.")
        elif response.status_code == 403:
            raise Exception("Forbidden. Insufficient permissions.")
        elif response.status_code == 404:
            raise Exception("Resource not found.")
        else:
            raise Exception(f"HTTP error occurred: {response.status_code} - {response.text}")

    except requests.exceptions.RequestException as e:
        raise Exception(f"Request failed: {str(e)}")
